components.css:
.ds-btn-primary {
  font-family: "Readex Pro Variable", sans-serif;
  font-size: 16px;
  font-weight: 600;
  background: var(--action, #2563eb);
  color: #fff;
  border: 0;
  border-radius: 8px;
  min-height: 40px;
  padding: 8px 14px;
  display: inline-flex;
  align-items: center;
  width: fit-content;
  cursor: pointer;
  text-decoration: none;
}
.ds-btn-primary:hover { background: var(--action-ink, #1d4ed8); }
.ds-btn-primary:focus-visible { outline: 2px solid var(--action, #2563eb); outline-offset: 2px; }
.ds-btn-primary:disabled {
  background: var(--line, #e5e7eb);
  color: var(--muted, #4b5563);
  cursor: not-allowed;
}

.ds-btn-bordered {
  font-family: "Readex Pro Variable", sans-serif;
  font-size: 16px;
  background: var(--surface, #ffffff);
  color: var(--ink, #111827);
  border: 1px solid var(--line, #e5e7eb);
  border-radius: 8px;
  min-height: 40px;
  padding: 8px 14px;
  cursor: pointer;
}
.ds-btn-bordered:hover { background: #f3f4f6; }
.ds-btn-bordered:focus-visible { outline: 2px solid var(--action, #2563eb); outline-offset: 2px; }

.ds-btn-bordered {
  font-family: "Readex Pro Variable", sans-serif;
  font-size: 16px;
  background: var(--surface, #ffffff);
  color: var(--ink, #111827);
  border: 1px solid var(--line, #e5e7eb);
  border-radius: 8px;
  min-height: 40px;
  padding: 8px 14px;
  cursor: pointer;
}
.ds-btn-bordered:hover { background: #f3f4f6; }
.ds-btn-bordered:focus-visible { outline: 2px solid var(--action, #2563eb); outline-offset: 2px; }
.ds-btn-quiet {
  font-family: "Readex Pro Variable", sans-serif;
  font-size: 16px;
  background: transparent;
  color: var(--late, #b91c1c);
  border: 0;
  border-radius: 8px;
  min-height: 40px;
  padding: 8px 14px;
  margin-inline-start: 20px;
  cursor: pointer;
}
.ds-btn-quiet:hover { background: #f3f4f6; }
.ds-btn-quiet:focus-visible { outline: 2px solid var(--action, #2563eb); outline-offset: 2px; }

.ds-rail {
  width: 230px;
  background: var(--surface, #ffffff);
  border-inline-end: 1px solid var(--line, #e5e7eb);
  padding: 24px 16px 16px;
  display: flex;
  flex-direction: column;
  font-family: "Readex Pro Variable", sans-serif;
  color: var(--ink, #111827);
}
.ds-brand {
  font-size: 22px;
  font-weight: 700;
  color: var(--action, #2563eb);
  margin: 0 10px 4px;
}
.ds-brand-sub {
  margin: 0 10px 20px;
  color: var(--muted, #4b5563);
  font-size: 13px;
}
.ds-nav { display: flex; flex-direction: column; gap: 2px; }
.ds-nav-link {
  color: #374151;
  text-decoration: none;
  font-size: 14px;
  padding: 8px 10px;
  border-radius: 8px;
  min-height: 40px;
  display: flex;
  align-items: center;
}
.ds-nav-link:hover { background: #f3f4f6; }
.ds-nav-link.is-on {
  background: var(--action-tint, #eff6ff);
  color: var(--action-ink, #1d4ed8);
  font-weight: 600;
}
.ds-nav-link:focus-visible { outline: 2px solid var(--action, #2563eb); outline-offset: 2px; }
.ds-foot {
  margin-top: 24px;
  padding: 16px 10px 0;
  border-top: 1px solid var(--line, #e5e7eb);
}
.ds-foot strong { display: block; font-size: 14px; }
.ds-foot span { color: var(--muted, #4b5563); font-size: 13px; }
.ds-lang {
  margin-top: 10px;
  background: transparent;
  border: 1px solid var(--line, #e5e7eb);
  border-radius: 8px;
  min-height: 40px;
  padding: 0 12px;
  cursor: pointer;
  font: inherit;
  color: inherit;
}
.ds-lang:hover { border-color: var(--action, #2563eb); }
.ds-lang:focus-visible { outline: 2px solid var(--action, #2563eb); outline-offset: 2px; }

.ds-metrics {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 14px;
  margin: 0;
  padding: 0;
  list-style: none;
  font-family: "Readex Pro Variable", sans-serif;
}
.ds-metric {
  background: var(--surface, #ffffff);
  border: 1px solid var(--line, #e5e7eb);
  border-radius: var(--radius, 12px);
  padding: 16px;
}
.ds-metric span {
  display: block;
  color: var(--muted, #4b5563);
  font-size: 14px;
}
.ds-metric strong {
  display: block;
  margin-top: 6px;
  font-size: 32px;
  font-weight: 600;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
  color: var(--ink, #111827);
}

.ds-filter {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 4px;
  color: var(--muted, #4b5563);
  font-family: "Readex Pro Variable", sans-serif;
  font-size: 14px;
}
.ds-filter select {
  width: 100%;
  max-width: 240px;
  min-height: 40px;
  border: 1px solid var(--line, #e5e7eb);
  border-radius: 8px;
  background: var(--surface, #ffffff);
  color: var(--ink, #111827);
  padding: 0 10px;
  font: inherit;
  caret-color: var(--action, #2563eb);
}
.ds-filter select:focus-visible { outline: 2px solid var(--action, #2563eb); outline-offset: 2px; }

.ds-notice {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: var(--notice, #dbeafe);
  border: 1px solid #bfdbfe;
  border-radius: 8px;
  padding: 10px 12px;
  font-family: "Readex Pro Variable", sans-serif;
  font-size: 16px;
  color: var(--ink, #111827);
}
.ds-btn-bordered {
  font-family: "Readex Pro Variable", sans-serif;
  font-size: 16px;
  background: var(--surface, #ffffff);
  color: var(--ink, #111827);
  border: 1px solid var(--line, #e5e7eb);
  border-radius: 8px;
  min-height: 40px;
  padding: 8px 14px;
  cursor: pointer;
}
.ds-btn-bordered:hover { background: #f3f4f6; }
.ds-btn-bordered:focus-visible { outline: 2px solid var(--action, #2563eb); outline-offset: 2px; }

.ds-panel {
  display: grid;
  grid-template-columns: minmax(0, 0.85fr) minmax(0, 1.25fr);
  gap: 28px;
  align-items: start;
  background: var(--surface, #ffffff);
  border: 1px solid var(--line, #e5e7eb);
  border-radius: var(--radius, 12px);
  padding: 18px 18px 8px;
  font-family: "Readex Pro Variable", sans-serif;
  color: var(--ink, #111827);
}
.ds-panel h2 {
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.02em;
  margin: 0 0 12px;
}
.ds-bars {
  display: flex;
  align-items: flex-end;
  gap: 12px;
  min-height: 180px;
}
.ds-bar {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.ds-track { height: 120px; display: flex; align-items: flex-end; }
.ds-col {
  width: 36px;
  background: var(--action, #2563eb);
  border-radius: 6px 6px 0 0;
}
.ds-n { font-variant-numeric: tabular-nums; font-weight: 600; }
.ds-lab { font-size: 13px; color: var(--muted, #4b5563); text-align: center; }
.ds-table { width: 100%; border-collapse: collapse; font-variant-numeric: tabular-nums; }
.ds-table th, .ds-table td {
  text-align: start;
  padding: 10px 8px;
  border-bottom: 1px solid var(--line, #e5e7eb);
  vertical-align: top;
}
.ds-table th { font-weight: 500; color: var(--muted, #4b5563); font-size: 14px; }
.ds-table tbody tr:hover td { background: #f8fafc; }
.ds-late { color: var(--late, #b91c1c); font-weight: 600; }
.ds-ok { color: var(--ontime, #047857); font-weight: 600; }

.ds-money { font-family: "Readex Pro Variable", sans-serif; }
.ds-note {
  color: var(--muted, #4b5563);
  font-size: 14px;
  max-width: 62ch;
  margin: 0 0 12px;
}
.ds-compare {
  display: flex;
  height: 12px;
  border-radius: 999px;
  overflow: hidden;
  background: var(--line, #e5e7eb);
}
.ds-rev { background: var(--action, #2563eb); }
.ds-exp { background: #93c5fd; }

.ds-queue {
  display: grid;
  grid-template-rows: 1fr;
  transition: grid-template-rows 240ms cubic-bezier(0.16, 1, 0.3, 1);
  font-family: "Readex Pro Variable", sans-serif;
  color: var(--ink, #111827);
  font-size: 16px;
}
@media (prefers-reduced-motion: reduce) {
  .ds-queue { transition: none; }
}
.ds-leave { list-style: none; margin: 0; padding: 0; }
.ds-leave li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 12px 0;
  border-bottom: 1px solid var(--line, #e5e7eb);
}
.ds-leave p { margin: 0; }
